const body = $input.first().json.body || {};
const booking = body.booking || {};
const customer = booking.customer || {};
const totalUSD = parseFloat(String(booking.totalUSD || 0).replace(/[^0-9.\-]/g, '')) || 0;
const adults = parseInt(booking.adults || 0, 10);
const children = parseInt(booking.children || 0, 10);
const passengers = adults + children;
const email = String(customer.email || '').toLowerCase().trim();
const phone = String(customer.phone || '').trim();

const disposableDomains = ['mailinator.com', 'tempmail.com', '10minutemail.com', 'guerrillamail.com', 'trashmail.com', 'throwawaymail.com', 'yopmail.com', 'sharklasers.com'];
const isDisposable = disposableDomains.some(d => email.endsWith('@' + d));

const reasons = [];
let score = 0;

// Regla 1: Monto atípico muy alto
if (totalUSD >= 2000) {
  reasons.push(`Monto elevado: $${totalUSD} USD`);
  score += 40;
}

// Regla 2: Correo temporal / desechable
if (isDisposable) {
  reasons.push(`Dominio de email desechable detectado: ${email}`);
  score += 60;
}

// Regla 3: Grupo grande sin teléfono de contacto
if (passengers >= 8 && (!phone || phone.length < 7)) {
  reasons.push(`Grupo grande (${passengers} pax) sin teléfono de contacto`);
  score += 35;
}

// Regla 4: Email ausente o no válido
if (!email || !email.includes('@')) {
  reasons.push('Falta correo electrónico válido');
  score += 30;
}

const isSuspicious = score >= 50;
const riskScore = score >= 70 ? 'alto' : (score >= 35 ? 'medio' : 'bajo');

return [{
  json: {
    isSuspicious,
    riskScore,
    score,
    reasons: reasons.join('; '),
    bookingId: booking.bookingId || '',
    docId: booking._id || booking.id || booking.bookingId || '',
    tourName: booking.tourName || '',
    totalUSD,
    customerName: customer.name || 'Sin nombre',
    customerEmail: email,
    customerPhone: phone,
    createdAt: new Date().toISOString()
  }
}];

